"""Potentiometer Gaze Controller (OLED + Pot + Button)"""
from espzero import OLED, Pot, Button
from time import sleep

oled = OLED(scl=47, sda=21)
pot = Pot(1)          # ADC1 pin (GPIO 1)
btn = Button(5)

while True:
    if btn.is_pressed:
        oled.show_face("love")
    else:
        # Map dial (0.0 ~ 1.0) to eye gaze X (-1.0 ~ +1.0)
        gaze_x = (pot.value * 2.0) - 1.0
        oled.look_at(gaze_x, 0.0, emotion="happy")
    sleep(0.05)
